package com.example.madfinalproject.coach;
import com.example.madfinalproject.models.VisaInterviewQuestion; import com.example.madfinalproject.utils.LogUtils; import com.google.firebase.auth.FirebaseAuth; import com.google.firebase.firestore.FieldValue; import com.google.firebase.firestore.FirebaseFirestore; import java.util.HashMap; import java.util.Map;
public final class BookmarkRepository { private static final BookmarkRepository INSTANCE=new BookmarkRepository(); public static BookmarkRepository getInstance(){return INSTANCE;} public void save(VisaInterviewQuestion q,boolean favourite){String uid=FirebaseAuth.getInstance().getUid();if(uid==null)uid="guest";Map<String,Object>d=new HashMap<>();d.put("userId",uid);d.put("questionId",q.getId());d.put("country",q.getCountry());d.put("category",q.getCategory());d.put("question",q.getQuestion());d.put("favourite",favourite);d.put("createdAt",FieldValue.serverTimestamp());FirebaseFirestore.getInstance().collection("userBookmarks").document(uid+"_"+q.getId()).set(d).addOnSuccessListener(v->LogUtils.d("VisaCoach","Bookmark added: "+q.getId())).addOnFailureListener(e->LogUtils.e("VisaCoach","Bookmark failed",e));} }
